import React, { useState, useRef, useEffect } from 'react';

const CameraProcessor = ({ colorblindType, mode }) => {
  const [streaming, setStreaming] = useState(false);
  const [error, setError] = useState(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const animationFrameRef = useRef(null);
  const streamingRef = useRef(false);

  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  const applyColorFilter = (imageData, colorblindType, mode) => {
    const data = imageData.data;
    
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      
      if (mode === 'simulate') {
        if (colorblindType === 'protanopia') {
          data[i] = Math.round(r * 0.567 + g * 0.433);
          data[i + 1] = Math.round(r * 0.558 + g * 0.442);
          data[i + 2] = Math.round(g * 0.242 + b * 0.758);
        } else if (colorblindType === 'deuteranopia') {
          data[i] = Math.round(r * 0.625 + g * 0.375);
          data[i + 1] = Math.round(r * 0.7 + g * 0.3);
          data[i + 2] = Math.round(g * 0.3 + b * 0.7);
        } else if (colorblindType === 'tritanopia') {
          data[i] = Math.round(r * 0.95 + g * 0.05);
          data[i + 1] = Math.round(g * 0.433 + b * 0.567);
          data[i + 2] = Math.round(g * 0.475 + b * 0.525);
        }
      } else if (mode === 'enhance') {
        // Enhance mode - increase color saturation
        const max = Math.max(r, g, b);
        const min = Math.min(r, g, b);
        const l = (max + min) / 2;
        
        if (colorblindType === 'protanopia' || colorblindType === 'deuteranopia') {
          // Enhance blue channel
          data[i + 2] = Math.round(Math.min(255, b * 1.3));
        } else if (colorblindType === 'tritanopia') {
          // Enhance red channel
          data[i] = Math.round(Math.min(255, r * 1.3));
        }
      }
    }
  };

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { 
          width: { ideal: 1280 }, 
          height: { ideal: 720 }
        }
      });
      
      streamRef.current = stream;
      streamingRef.current = true;
      
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.muted = true;
        videoRef.current.autoplay = true;
        videoRef.current.playsInline = true;
        
        // Trigger play
        const playPromise = videoRef.current.play();
        if (playPromise !== undefined) {
          playPromise.catch(err => {
            console.error('Autoplay error:', err);
            setError('Could not start video playback: ' + err.message);
          });
        }
        
        // Wait for video to be ready
        videoRef.current.onloadedmetadata = () => {
          console.log('Video metadata loaded:', videoRef.current.videoWidth, 'x', videoRef.current.videoHeight);
          setStreaming(true);
          setError(null);
          
          // Set canvas dimensions AFTER video is loaded
          if (canvasRef.current) {
            canvasRef.current.width = videoRef.current.videoWidth || 1280;
            canvasRef.current.height = videoRef.current.videoHeight || 720;
            console.log('Canvas dimensions set to:', canvasRef.current.width, 'x', canvasRef.current.height);
            
            // Start processing immediately
            if (streamingRef.current) {
              processFrames();
            }
          }
        };
        
        videoRef.current.onerror = (err) => {
          console.error('Video element error:', err);
          setError('Video stream error');
          setStreaming(false);
          streamingRef.current = false;
        };
      }
    } catch (err) {
      setError('Failed to access camera: ' + err.message);
      console.error('Camera error:', err);
      setStreaming(false);
      streamingRef.current = false;
    }
  };

  const stopCamera = () => {
    streamingRef.current = false;
    
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    
    setStreaming(false);
  };

  const processFrames = () => {
    if (!videoRef.current || !canvasRef.current || !streamingRef.current) {
      return;
    }

    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });

    try {
      // Check if video has data
      if (video.readyState >= 2) {
        // Draw video frame to canvas
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        
        // Apply color filter
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        applyColorFilter(imageData, colorblindType, mode);
        ctx.putImageData(imageData, 0, 0);
      }
    } catch (err) {
      console.error('Frame processing error:', err);
    }

    if (streamingRef.current) {
      animationFrameRef.current = requestAnimationFrame(processFrames);
    }
  };

  return (
    <div className="component-container">
      <h2>Live Camera Feed</h2>
      
      <div
        className="upload-area"
        style={{ 
          textAlign: 'center',
          padding: '40px 20px',
          border: '2px dashed #ccc',
          borderRadius: '8px',
          backgroundColor: '#fafafa',
          cursor: streaming ? 'default' : 'pointer'
        }}
      >
        {!streaming ? (
          <>
            <p style={{ fontSize: '16px', marginBottom: '10px' }}>Ready to start live camera feed</p>
            <p style={{ fontSize: '14px', color: '#666', marginBottom: '20px' }}>
              Click the button below to activate your camera
            </p>
          </>
        ) : (
          <p style={{ fontSize: '16px' }}>Camera is active</p>
        )}
      </div>

      {error && <div className="error" style={{ marginTop: '15px' }}>{error}</div>}

      {streaming && (
        <div className="camera-container" style={{ marginTop: '20px' }}>
          <video
            ref={videoRef}
            muted
            autoPlay
            playsInline
            style={{ display: 'none' }}
          />
          <canvas
            ref={canvasRef}
            width={1280}
            height={720}
            style={{ maxWidth: '100%', height: 'auto', border: '2px solid #ddd', borderRadius: '8px', display: 'block', margin: '0 auto', backgroundColor: '#000' }}
          />
        </div>
      )}

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button
          className="button"
          onClick={streaming ? stopCamera : startCamera}
        >
          {streaming ? 'Stop Camera' : 'Start Camera'}
        </button>
      </div>
    </div>
  );
};

export default CameraProcessor;
